import React, { useState, useEffect } from 'react';
import { productAPI, orderAPI } from './api';
import LoadingAnimation from './LoadingAnimation'; // Import LoadingAnimation
import './GroceryAdminDashboard.css';

const getCorrectImagePath = (path) => {
  if (!path) {
    return ''; // Return an empty string for orders that might not have a slip
  }
  // Assume the path is always a full URL from Azure Blob Storage
  return path;
};

const AddProduct = ({ onAdd, onCancel }) => {
  const [productName, setProductName] = useState("");
  const [category, setCategory] = useState("");
  const [price, setPrice] = useState("");
  const [stockQuantity, setStockQuantity] = useState("");
  const [stockUnit, setStockUnit] = useState("");
  const [customStockUnit, setCustomStockUnit] = useState(""); // State for custom stock unit
  const [displayQuantity, setDisplayQuantity] = useState("");
  const [displayUnit, setDisplayUnit] = useState("");
  const [customDisplayUnit, setCustomDisplayUnit] = useState(""); // State for custom display unit
  const [description, setDescription] = useState("");
  const [discount, setDiscount] = useState("");
  const [imageFile, setImageFile] = useState(null);
  const [imagePreview, setImagePreview] = useState(null);

  const unitOptions = ["KG", "G", "ML", "L", "PACKET", "BOTTLE", "CAN", "OTHER"];

  // Clear one field
  const handleClear = (field) => {
    switch (field) {
      case "productName":
        setProductName("");
        break;
      case "category":
        setCategory("");
        break;
      case "price":
        setPrice("");
        break;
      case "stockQuantity":
        setStockQuantity("");
        break;
      case "stockUnit":
        setStockUnit("");
        setCustomStockUnit("");
        break;
      case "displayQuantity":
        setDisplayQuantity("");
        break;
      case "displayUnit":
        setDisplayUnit("");
        setCustomDisplayUnit("");
        break;
      case "description":
        setDescription("");
        break;
      case "discount":
        setDiscount("");
        break;
      case "imageFile":
        setImageFile(null);
        setImagePreview(null);
        break;
      default:
        break;
    }
  };

  // Clear all fields
  const handleClearAll = () => {
    setProductName("");
    setCategory("");
    setPrice("");
    setStockQuantity("");
    setStockUnit("");
    setCustomStockUnit("");
    setDisplayQuantity("");
    setDisplayUnit("");
    setCustomDisplayUnit("");
    setDescription("");
    setDiscount("");
    setImageFile(null);
    setImagePreview(null);
  };

  // Image handler
  const handleImageChange = (e) => {
    const file = e.target.files[0];
    if (file) {
      setImageFile(file);
      setImagePreview(URL.createObjectURL(file));
    }
  };

  // Convert safely → empty → 0
  const safeNumber = (val) => {
    if (val === "" || val === null || isNaN(val)) return 0;
    return Number(val);
  };

  // Submit form
  const handleSubmit = async (e) => {
    e.preventDefault();

    const formData = new FormData();
    formData.append("name", productName);
    formData.append("category", category);
    formData.append("originalPrice", safeNumber(price));
    formData.append("stockQuantity", safeNumber(stockQuantity));
    formData.append("displayQuantity", safeNumber(displayQuantity));
    formData.append("description", description);
    formData.append("discount", safeNumber(discount));

    if (stockUnit === "OTHER") {
      formData.append("stockUnit", "OTHER");
      formData.append("customStockUnit", customStockUnit);
    } else {
      formData.append("stockUnit", stockUnit);
    }

    if (displayUnit === "OTHER") {
      formData.append("displayUnit", "OTHER");
      formData.append("customDisplayUnit", customDisplayUnit);
    } else {
      formData.append("displayUnit", displayUnit);
    }

    if (imageFile) {
      formData.append("imageFile", imageFile);
    }

    try {
      await productAPI.addProduct(formData);
      alert("Product added successfully!");
      handleClearAll();
      onAdd();
    } catch (error) {
      console.error("Error adding product:", error);
      alert("Server error. Check backend logs.");
    }
  };

  return (
    <div className="add-product-container">
      <h2 className="form-title">
        <span className="form-title-icon">+</span> Add New Product
      </h2>

      <form className="form-grid" onSubmit={handleSubmit}>
        {/* Left column */}
        <div className="form-column">
          <div className="form-group">
            <label>Product Name *</label>
            <input
              type="text"
              placeholder="Enter product name"
              value={productName}
              onChange={(e) => setProductName(e.target.value)}
              className="white-input"
              required
            />
            <button
              type="button"
              className="clear-btn"
              onClick={() => handleClear("productName")}
            >
              Clear
            </button>
          </div>

          <div className="form-group">
            <label>Category *</label>
            <select
              value={category}
              onChange={(e) => setCategory(e.target.value)}
              className="white-input"
              required
            >
              <option value="">-- Select Category --</option>
              <option value="vegetables">Vegetables</option>
              <option value="fruits">Fruits</option>
              <option value="beverages">Beverages</option>
              <option value="canned food">Canned Food</option>
              <option value="dairy">Dairy</option>
              <option value="meat">Meat</option>
              <option value="sea food">Sea Food</option>
              <option value="snacks">Snacks & Sweets</option>
            </select>
            <button
              type="button"
              className="clear-btn"
              onClick={() => handleClear("category")}
            >
              Clear
            </button>
          </div>

          <div className="form-group">
            <label>Price (Rs.) *</label>
            <input
              type="number"
              placeholder="Enter price"
              value={price}
              min="0"
              onChange={(e) => setPrice(e.target.value)}
              className="white-input"
              required
            />
            <button
              type="button"
              className="clear-btn"
              onClick={() => handleClear("price")}
            >
              Clear
            </button>
          </div>

          <div className="form-group stock-group">
            <label>Stock Quantity</label>
            <input
              type="number"
              placeholder="Enter stock quantity"
              value={stockQuantity}
              min="0"
              onChange={(e) => setStockQuantity(e.target.value)}
              className="white-input"
            />
            <select
              value={stockUnit}
              onChange={(e) => setStockUnit(e.target.value)}
              className="white-input"
            >
              <option value="">-- Select Unit --</option>
              {unitOptions.map((unit) => (
                <option key={unit} value={unit}>
                  {unit}
                </option>
              ))}
            </select>
            {stockUnit === "OTHER" && (
              <input
                type="text"
                placeholder="Enter custom unit"
                value={customStockUnit}
                onChange={(e) => setCustomStockUnit(e.target.value)}
                className="white-input"
              />
            )}
            <button
              type="button"
              className="clear-btn"
              onClick={() => {
                handleClear("stockQuantity");
                handleClear("stockUnit");
              }}
            >
              Clear
            </button>
          </div>

          <div className="form-group display-group">
            <label>Display Quantity (For customers)</label>
            <input
              type="number"
              placeholder="Enter display quantity"
              value={displayQuantity}
              min="0"
              onChange={(e) => setDisplayQuantity(e.target.value)}
              className="white-input"
            />
            <select
              value={displayUnit}
              onChange={(e) => setDisplayUnit(e.target.value)}
              className="white-input"
            >
              <option value="">-- Select Unit --</option>
              {unitOptions.map((unit) => (
                <option key={unit} value={unit}>
                  {unit}
                </option>
              ))}
            </select>
            {displayUnit === "OTHER" && (
              <input
                type="text"
                placeholder="Enter custom unit"
                value={customDisplayUnit}
                onChange={(e) => setCustomDisplayUnit(e.target.value)}
                className="white-input"
              />
            )}
            <button
              type="button"
              className="clear-btn"
              onClick={() => {
                handleClear("displayQuantity");
                handleClear("displayUnit");
              }}
            >
              Clear
            </button>
          </div>
        </div>

        {/* Right column */}
        <div className="form-column right">
          <div className="form-group">
            <label>Description</label>
            <textarea
              placeholder="Enter description"
              value={description}
              onChange={(e) => setDescription(e.target.value)}
              className="white-input"
            ></textarea>
            <button
              type="button"
              className="clear-btn"
              onClick={() => handleClear("description")}
            >
              Clear
            </button>
          </div>

          <div className="form-group">
            <label>Discount (%)</label>
            <input
              type="number"
              placeholder="0"
              value={discount}
              min="0"
              onChange={(e) => setDiscount(e.target.value)}
              className="white-input"
            />
            <button
              type="button"
              className="clear-btn"
              onClick={() => handleClear("discount")}
            >
              Clear
            </button>
          </div>

          <div className="form-group image-upload aligned-left">
            <label className="image-label">Upload Image</label>
            <div className="upload-box">
              <input
                id="product-image"
                type="file"
                accept="image/*"
                onChange={handleImageChange}
                style={{ display: "none" }}
              />
              <label htmlFor="product-image" className="upload-label">
                {imagePreview ? (
                  <img
                    src={imagePreview}
                    alt="Preview"
                    className="image-preview"
                  />
                ) : (
                  <span className="upload-icon">📷</span>
                )}
              </label>
            </div>
            <button
              type="button"
              className="clear-btn"
              onClick={() => handleClear("imageFile")}
            >
              Clear
            </button>
          </div>
        </div>

        {/* Action buttons */}
        <div className="form-actions">
          <button type="submit" className="submit-btn">
            Add Product
          </button>
          <button
            type="button"
            className="clear-all-btn"
            onClick={handleClearAll}
          >
            Clear All
          </button>
          <button
            type="button"
            className="bbtn-secondary"
            onClick={onCancel}
          >
            Cancel
          </button>
        </div>
      </form>
    </div>
  );
};

const GroceryAdminDashboard = () => {
  const unitOptions = ["KG", "G", "ML", "L", "PACKET", "BOTTLE", "CAN", "OTHER"];
  const [activeTab, setActiveTab] = useState('overview');
  const [showAddProduct, setShowAddProduct] = useState(false);
  const [showEditProduct, setShowEditProduct] = useState(false);
  const [editingProduct, setEditingProduct] = useState(null);
  const [adminName, setAdminName] = useState('Admin');
  const [selectedSlip, setSelectedSlip] = useState(null);
  const [showSlipModal, setShowSlipModal] = useState(false);
  const [productSearch, setProductSearch] = useState('');
  const [orderSearch, setOrderSearch] = useState('');
  const [paymentSlipSearch, setPaymentSlipSearch] = useState('');
  const [loading, setLoading] = useState(true);

  const [orders, setOrders] = useState([]);
  const [products, setProducts] = useState([]);
  const [paymentSlips, setPaymentSlips] = useState([]);

  useEffect(() => {
    const userNickname = localStorage.getItem('username');
    if (userNickname) {
      setAdminName(userNickname);
    }
    const fetchData = async () => {
      setLoading(true);
      await Promise.all([fetchProducts(), fetchOrders(), fetchPaymentSlips()]);
      setLoading(false);
    };
    fetchData();

    const handleOrderPlaced = () => {
      fetchOrders();
      fetchPaymentSlips();
    };

    window.addEventListener('order-placed', handleOrderPlaced);

    return () => {
      window.removeEventListener('order-placed', handleOrderPlaced);
    };
  }, []);

  const fetchPaymentSlips = async () => {
    try {
      const response = await orderAPI.getOrdersWithTransferSlips();
      setPaymentSlips(response.data);
    } catch (error) {
      console.error('Failed to fetch payment slips:', error);
    }
  };

  const fetchOrders = async () => {
    try {
      const response = await orderAPI.getAllOrders();
      setOrders(response.data);
    } catch (error) {
      console.error('Failed to fetch orders:', error);
    }
  };

  const fetchProducts = async () => {
    try {
      const response = await productAPI.getAllProducts();
      setProducts(response.data);
    } catch (error) {
      console.error('Failed to fetch products:', error);
    }
  };

  const handleEditProduct = async () => {
    if (editingProduct) {
      try {
        const formData = new FormData();
        formData.append("name", editingProduct.name);
        formData.append("category", editingProduct.category);
        formData.append("originalPrice", editingProduct.originalPrice);
        formData.append("discount", editingProduct.discount);
        formData.append("stockQuantity", editingProduct.stockQuantity);
        formData.append("displayQuantity", editingProduct.displayQuantity);
        formData.append("description", editingProduct.description);

        if (editingProduct.stockUnit === "OTHER") {
          formData.append("stockUnit", "OTHER");
          formData.append("customStockUnit", editingProduct.customStockUnit);
        } else {
          formData.append("stockUnit", editingProduct.stockUnit);
        }

        if (editingProduct.displayUnit === "OTHER") {
          formData.append("displayUnit", "OTHER");
          formData.append("customDisplayUnit", editingProduct.customDisplayUnit);
        } else {
          formData.append("displayUnit", editingProduct.displayUnit);
        }

        await productAPI.updateProduct(editingProduct.id, formData);
        setShowEditProduct(false);
        setEditingProduct(null);
        fetchProducts();
      } catch (error) {
        console.error('Failed to edit product:', error);
      }
    }
  };

  const handleStatusChange = async (orderId, status) => {
    try {
      await orderAPI.updateOrderStatus(orderId, status);
      // Refresh both orders and payment slips as their status might be linked
      fetchOrders();
      fetchPaymentSlips();
    } catch (error) {
      console.error('Failed to update order status:', error);
    }
  };

  // ===================================================================================
  //  FIX: ADDED THE MISSING updateSlipStatus FUNCTION
  // ===================================================================================
  const updateSlipStatus = (status) => {
    if (selectedSlip) {
      handleStatusChange(selectedSlip.id, status);
      setShowSlipModal(false);
    }
  };
  // ===================================================================================

  const handleDeleteProduct = async (id) => {
    try {
      await productAPI.deleteProduct(id);
      fetchProducts();
    } catch (error) {
      console.error('Failed to delete product:', error);
    }
  };

  const openEditModal = (product) => {
    setEditingProduct({ ...product, customStockUnit: '', customDisplayUnit: '' });
    setShowEditProduct(true);
  };

  const viewPaymentSlip = (slip) => {
    setSelectedSlip(slip);
    setShowSlipModal(true);
  };

